/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  let total = getFact(line.length);

  const obj = {};
  for (let c of line) {
    obj[c] ? obj[c]++ : (obj[c] = 1);
  }

  for (let k in obj) {
    if (obj[k] > 1) {
      total /= getFact(obj[k]);
    }
  }

  console.log(total);
});

function getFact(n) {
  let fact = 1;
  for (let i = 1; i <= n; i++) {
    fact *= i;
  }
  return fact;
}

